#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/device.h>
#include <zephyr/sys/ring_buffer.h>

#include <zephyr/modem/pipe.h>

#include <string.h>

/* Test state */
enum test_modem_pipe_event {
	TEST_MODEM_PIPE_EVENT_OPENED_BIT,
	TEST_MODEM_PIPE_EVENT_CLOSED_BIT,
	TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT,
	TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT,
};

static atomic_t test_state;
static K_SEM_DEFINE(test_sem, 0, 1);

static int wait_for_event(uint32_t event_bit)
{
	if (atomic_test_and_clear_bit(&test_state, event_bit)) {
		return 0;
	}

	return k_sem_take(&test_sem, K_SECONDS(1));
}

static void test_pipe_event_handler(struct modem_pipe *pipe,
				    enum modem_pipe_event event,
				    void *user_data)
{
	ARG_UNUSED(pipe);
	ARG_UNUSED(user_data);

	switch (event) {
	case MODEM_PIPE_EVENT_OPENED:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_OPENED_BIT);
		break;

	case MODEM_PIPE_EVENT_CLOSED:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_CLOSED_BIT);
		break;

	case MODEM_PIPE_EVENT_TRANSMIT_IDLE:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT);
		break;

	case MODEM_PIPE_EVENT_RECEIVE_READY:
		atomic_set_bit(&test_state, TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT);
		break;
	}

	k_sem_give(&test_sem);
}

/* Mock pipe backend */
static uint8_t mock_pipe_backend_tx_buf[128];
static uint8_t mock_pipe_backend_rx_buf[128];
static struct ring_buf mock_pipe_backend_tx_rb;
static struct ring_buf mock_pipe_backend_rx_rb;

static void mock_pipe_backend_init(void)
{
	ring_buf_init(&mock_pipe_backend_tx_rb, sizeof(mock_pipe_backend_tx_buf),
		      mock_pipe_backend_tx_buf);

	ring_buf_init(&mock_pipe_backend_rx_rb, sizeof(mock_pipe_backend_rx_buf),
		      mock_pipe_backend_rx_buf);
}

static int mock_pipe_backend_open(void *data)
{
	return 0;
}

static int mock_pipe_backend_transmit(void *data, const uint8_t *buf, size_t size)
{
	return ring_buf_put(&mock_pipe_backend_tx_rb, buf, size);
}

static int mock_pipe_backend_receive(void *data, uint8_t *buf, size_t size)
{
	return ring_buf_get(&mock_pipe_backend_rx_rb, buf, size);
}

static int mock_pipe_backend_close(void *data)
{
	return 0;
}

static const struct modem_pipe_backend mock_pipe_backend = {
	.open = mock_pipe_backend_open,
	.transmit = mock_pipe_backend_transmit,
	.receive = mock_pipe_backend_receive,
	.close = mock_pipe_backend_close,
};

/* Define pipe */
static uint8_t pipe_buf[128];
MODEM_PIPE_DEFINE(pipe, pipe_buf, sizeof(pipe_buf), &mock_pipe_backend, NULL);

static void *test_modem_pipe_setup(void)
{
	mock_pipe_backend_init();
	modem_pipe_attach(&pipe, test_pipe_event_handler, NULL);
	return NULL;
}

static void test_modem_pipe_before(void *data)
{
	atomic_set(&test_state, 0);
	k_sem_reset(&test_sem);
}

static void test_modem_pipe_after(void *data)
{
	if (modem_pipe_is_open(&pipe)) {
		modem_pipe_close_async(&pipe);
		wait_for_event(TEST_MODEM_PIPE_EVENT_CLOSED_BIT);
	}
}

ZTEST_SUITE(modem_pipe, NULL, test_modem_pipe_setup, test_modem_pipe_before,
	    test_modem_pipe_after, NULL);

ZTEST(modem_pipe, test_async_open_close)
{
	int ret;

	/* Test that pipe can be opened asynchronously */
	modem_pipe_open_async(&pipe);
	ret = wait_for_event(TEST_MODEM_PIPE_EVENT_OPENED_BIT);
	zassert_ok(ret, "event wait timed out");
	zassert_true(modem_pipe_is_open(&pipe), "pipe should be open");

	/* Test that pipe can be closed asynchronously */
	modem_pipe_close_async(&pipe);
	ret = wait_for_event(TEST_MODEM_PIPE_EVENT_CLOSED_BIT);
	zassert_ok(ret, "event wait timed out");
	zassert_false(modem_pipe_is_open(&pipe), "pipe should be closed");
}

ZTEST(modem_pipe, test_sync_open_close)
{
	int ret;

	/* Test that pipe can be opened synchronously */
	ret = modem_pipe_open(&pipe, K_SECONDS(1));
	zassert_ok(ret, "pipe open failed");
	zassert_true(modem_pipe_is_open(&pipe), "pipe should be open");

	/* Test that pipe can be closed synchronously */
	ret = modem_pipe_close(&pipe, K_SECONDS(1));
	zassert_ok(ret, "pipe close failed");
	zassert_false(modem_pipe_is_open(&pipe), "pipe should be closed");
}

ZTEST(modem_pipe, test_async_transmit)
{
	int ret;
	uint8_t tx_buf[10] = "0123456789";
	uint8_t rx_buf[sizeof(tx_buf)];

	/* Open pipe */
	ret = modem_pipe_open(&pipe, K_SECONDS(1));
	zassert_ok(ret, "pipe open failed");

	/* Transmit */
	ret = modem_pipe_transmit(&pipe, tx_buf, sizeof(tx_buf));
	zassert_ok(ret, "pipe transmit failed");

	/* Wait for transmit idle event */
	ret = wait_for_event(TEST_MODEM_PIPE_EVENT_TRANSMIT_IDLE_BIT);
	zassert_ok(ret, "event wait timed out");

	/* Test that data was transmitted to backend */
	ret = ring_buf_get(&mock_pipe_backend_tx_rb, rx_buf, sizeof(rx_buf));
	zassert_equal(ret, sizeof(rx_buf), "incorrect number of bytes in backend tx buffer");
	zassert_mem_equal(tx_buf, rx_buf, sizeof(tx_buf), "transmitted data mismatch");
}

ZTEST(modem_pipe, test_async_receive)
{
	int ret;
	uint8_t tx_buf[10] = "0123456789";
	uint8_t rx_buf[sizeof(tx_buf)];

	/* Open pipe */
	ret = modem_pipe_open(&pipe, K_SECONDS(1));
	zassert_ok(ret, "pipe open failed");

	/* Put data in backend rx buffer */
	ret = ring_buf_put(&mock_pipe_backend_rx_rb, tx_buf, sizeof(tx_buf));
	zassert_equal(ret, sizeof(tx_buf), "failed to put data in backend rx buffer");

	/* Signal receive ready */
	modem_pipe_notify_receive_ready(&pipe);
	ret = wait_for_event(TEST_MODEM_PIPE_EVENT_RECEIVE_READY_BIT);
	zassert_ok(ret, "event wait timed out");

	/* Test that data was received from backend */
	ret = modem_pipe_receive(&pipe, rx_buf, sizeof(rx_buf));
	zassert_equal(ret, sizeof(rx_buf), "incorrect number of bytes received");
	zassert_mem_equal(tx_buf, rx_buf, sizeof(tx_buf), "received data mismatch");
}
